# inspect 8-connected components and differences in demos
from collections import Counter, deque

def comps(g, conn=8):
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    pts={(r,c) for r in range(len(g)) for c in range(len(g[0])) if g[r][c]!=bg}
    out=[]
    while pts:
        seed=pts.pop(); q=[seed]; cc={seed}
        while q:
            r,c=q.pop()
            for dr in [-1,0,1]:
                for dc in [-1,0,1]:
                    if (not dr and not dc) or (conn==4 and abs(dr)+abs(dc)!=1): continue
                    p=(r+dr,c+dc)
                    if p in pts: pts.remove(p); cc.add(p); q.append(p)
        out.append(cc)
    return sorted(out,key=lambda x:min(x))
